sys_ws_operation.operation_script:
(function process(request, response) {

    var bookingNumber = request.pathParams.booking_number;
    var token = request.queryParams.token;

    if (!bookingNumber || !token) {
        response.setStatus(400);

        return {
            success: false,
            message: 'Booking number and verification token are required.'
        };
    }

    var booking = new GlideRecord(
        'x_1958892_smart_0_parking_booking'
    );

    booking.addQuery('booking_number', bookingNumber);
    booking.addQuery('verification_token', token);
    booking.query();

    if (!booking.next()) {
        response.setStatus(404);

        return {
            success: false,
            message: 'Invalid parking booking or verification token.'
        };
    }

    return {
        success: true,
        message: 'Parking booking verified successfully.',
        booking_number: booking.getValue('booking_number'),
        booking_status: booking.getDisplayValue('booking_status'),
        start_time: booking.getDisplayValue('start_time'),
        end_time: booking.getDisplayValue('end_time')
    };

})(request, response);
